  if (sb < 0) { neg ^= 1; sb = -sb; }
  __int128 num = sa * (__int128)1000000;
  __int128 q = num / sb;
  __int128 r = num % sb;
  if (r * 2 > sb) { q += 1; }
  else if (r * 2 == sb && (q & 1)) { q += 1; }
